def change_base(x: int, base: int):
    if x == 0:
        return "0"

    digits = []
    is_negative = x < 0
    if is_negative:
        x = -x

    while x > 0:
        digits.append(str(x % base))
        x //= base

    if is_negative:
        digits.append('-')

    return ''.join(reversed(digits))
